package com.bank.kahn;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.logging.Logger;

// Orders settlement tasks by precedence using Kahn's algorithm (BFS topo sort).
public class SettlementScheduler {

    private static final Logger log = Logger.getLogger(SettlementScheduler.class.getName());

    public List<Integer> schedule(int numTasks, int[][] precedences) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numTasks; i++) adj.add(new ArrayList<>());
        int[] inDegree = new int[numTasks];
        for (int[] p : precedences) {
            // p[0] must come before p[1]
            adj.get(p[0]).add(p[1]);
            inDegree[p[1]]++;
        }

        Queue<Integer> ready = new ArrayDeque<>();
        for (int i = 0; i < numTasks; i++) {
            if (inDegree[i] == 0) ready.add(i); // no pending predecessor
        }

        List<Integer> order = new ArrayList<>();
        while (!ready.isEmpty()) {
            int task = ready.poll();
            order.add(task);
            for (int next : adj.get(task)) {
                if (--inDegree[next] == 0) ready.add(next);
            }
        }

        if (order.size() != numTasks) {
            log.info("Cycle detected; emitted " + order.size() + "/" + numTasks);
            return List.of();
        }
        log.info("Settlement order: " + order);
        return order;
    }
}
