package com.bank.kahn;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class KahnDemo {

    private static final Logger log = Logger.getLogger(KahnDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Settlement Task Scheduling (Kahn)");
        SettlementScheduler scheduler = new SettlementScheduler();
        // 0 before 1 and 2; 1 before 3; 2 before 3
        int[][] precedences = {{0, 1}, {0, 2}, {1, 3}, {2, 3}};
        scheduler.schedule(4, precedences); // e.g. [0,1,2,3]
    }
}
